const navy=Color(0xFF071827), navy2=Color(0xFF102B40), gold=Color(0xFFD7A84A), gold2=Color(0xFFF2CC75), page=Color(0xFFF5F7F9);
const green=Color(0xFF2BB866), blue=Color(0xFF2D98E6), purple=Color(0xFF7655D8), orange=Color(0xFFF39A2B), teal=Color(0xFF23AEBE);
String hashPass(String s)=>sha256.convert(utf8.encode(s)).toString();

class User{String username,name,role,password;User(this.username,this.name,this.role,this.password);Map<String,dynamic>toJson()=>{'u':username,'n':name,'r':role,'p':password};factory User.fromJson(Map<String,dynamic>x)=>User('${x['u']??''}','${x['n']??''}','${x['r']??'مشاور'}','${x['p']??''}');}
class Property{String code,type,title,address,owner,phone,price,area,rooms,year,link,agent;Property(this.code,this.type,this.title,this.address,this.owner,this.phone,this.price,this.area,this.rooms,this.year,this.link,this.agent);Map<String,dynamic>toJson()=>{'c':code,'t':type,'ti':title,'a':address,'o':owner,'ph':phone,'pr':price,'ar':area,'ro':rooms,'y':year,'l':link,'ag':agent};factory Property.fromJson(Map<String,dynamic>x)=>Property('${x['c']??''}','${x['t']??'آپارتمان'}','${x['ti']??''}','${x['a']??''}','${x['o']??''}','${x['ph']??''}','${x['pr']??''}','${x['ar']??''}','${x['ro']??''}','${x['y']??''}','${x['l']??''}','${x['ag']??''}');}
final properties=<Property>[];final clients=<String>[];final meetings=<String>[];User? currentUser;bool get manager=>currentUser?.role=='مدیر'||currentUser?.role=='مدیر فروش';

class Store{static Future<SharedPreferences>get p=>SharedPreferences.getInstance();static Future<List<User>>users()async{final x=await p;final raw=x.getString('users');if(raw==null){final u=[User('admin','مهندس مجتبی صفری','مدیر',hashPass('1234')),User('sales','خانم طهماسبی پور','مدیر فروش',hashPass('1234')),User('moshaver1','مشاور اول','مشاور',hashPass('1234'))];await saveUsers(u);return u;}return(jsonDecode(raw)as List).map((e)=>User.fromJson(Map<String,dynamic>.from(e))).toList();}static Future<void>saveUsers(List<User>u)async=>(await p).setString('users',jsonEncode(u.map((e)=>e.toJson()).toList()));static Future<void>load()async{final x=await p;try{properties..clear()..addAll((jsonDecode(x.getString('props')??'[]')as List).map((e)=>Property.fromJson(Map<String,dynamic>.from(e))));}catch(_){properties.clear();}clients..clear()..addAll(x.getStringList('clients')??[]);meetings..clear()..addAll(x.getStringList('meetings')??[]);}static Future<void>save()async{final x=await p;await x.setString('props',jsonEncode(properties.map((e)=>e.toJson()).toList()));await x.setStringList('clients',clients);await x.setStringList('meetings',meetings);}static Future<bool>dark()async=>(await p).getBool('dark')??false;static Future<void>setDark(bool v)async=>(await p).setBool('dark',v);}

