class PasswordDialog extends StatelessWidget{PasswordDialog({super.key});final x=TextEditingController();@override Widget build(BuildContext c)=>AlertDialog(title:const Text('تغییر رمز عبور'),content:TextField(controller:x,obscureText:true,decoration:const InputDecoration(labelText:'رمز جدید')),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('انصراف')),FilledButton(onPressed:()async{final u=await Store.users();for(final z in u){if(z.username==currentUser?.username)z.password=hashPass(x.text);}await Store.saveUsers(u);if(c.mounted)Navigator.pop(c);},child:const Text('ذخیره'))]);}
class UsersDialog extends StatelessWidget{UsersDialog({super.key});final name=TextEditingController();@override Widget build(BuildContext c)=>AlertDialog(title:const Text('مدیریت کاربران و مشاوران'),content:SizedBox(width:500,child:FutureBuilder<List<User>>(future:Store.users(),builder:(c,s){final u=s.data??[];return Column(mainAxisSize:MainAxisSize.min,children:[...u.map((x)=>ListTile(leading:Icon(x.role=='مشاور'?Icons.person_outline:Icons.admin_panel_settings,color:x.role=='مشاور'?blue:gold),title:Text(x.name),subtitle:Text('${x.username} • ${x.role}'))),if(manager)TextField(controller:name,decoration:const InputDecoration(labelText:'نام مشاور جدید'))];})),actions:[if(manager)FilledButton(onPressed:()async{if(name.text.trim().isEmpty)return;final u=await Store.users();u.add(User('moshaver${u.length}',name.text.trim(),'مشاور',hashPass('1234')));await Store.saveUsers(u);if(c.mounted)Navigator.pop(c);},child:const Text('افزودن مشاور')),TextButton(onPressed:()=>Navigator.pop(c),child:const Text('بستن'))]);}
